//      `next == "<<"` → `RenderedEndsWith(generated, "<<")`.
//   4. Increase CloseSpanWithinBudget reserve budgets from 30→60 in Phases 3/6,
//      40 in Phase 7, all-remaining in Phase 8.
//   5. Better AppendTaskGuidance emphasising complete combined formulas.
//   6. No expensive helpers: use only SafePenalizedConstrainedStep, ConstrainedStep,
//      UnconstrainedChunk, UnconstrainedStep, and CloseSpanWithinBudget.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedChunk loop): insideConstrainedOut stays false until
//     stoppedOnOpen; then EnterObservedConstrainedSpan sets currentConstrainedOut:=[]
//     which satisfies parser.IsValidPrefix([]) by precondition. Outside a span the
//     implication is vacuous.
//
//   Phase 2 (constrained loop), CloseConstrainedSpan branch: sets
//     insideConstrainedOut:=false so the implication becomes vacuous.
//   Phase 2, SafePenalizedConstrainedStep / ConstrainedStep branch: both helpers
//     return EOS or a parser-valid next token; AppendConstrainedToken's postcondition
//     ensures parser.IsValidPrefix(currentConstrainedOut ++ [next]).
//   EOS break exits with state unchanged (still valid).
//
//   Phase 3 (CloseSpanWithinBudget): library postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
//   Phase 4 (UnconstrainedStep loop): insideConstrainedOut stays false until
//     RenderedEndsWith detects "<<"; then EnterObservedConstrainedSpan sets
//     currentConstrainedOut:=[], valid by precondition. ✓
//
//   Phases 5, 6: identical arguments to Phases 2 and 3. ✓
//
//   Phase 7: OpenConstrainedSpan sets currentConstrainedOut:=[], valid. Inner
//     constrained loop is identical to Phase 2. CloseSpanWithinBudget same as Phase 3. ✓
//
//   Phase 8 (CloseSpanWithinBudget): same as Phase 3. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 1: UnconstrainedChunk adds stepsUsed to steps; its postcondition gives
//     |generatedOut| <= |generated_old| + stepsUsed. EnterObservedConstrainedSpan
//     adds 0 visible tokens and 0 steps. ✓
//
//   Phase 2, CloseConstrainedSpan branch: appends at most one ">>" token, steps+1. ✓
//   Phase 2, generate branch: SafePenalizedConstrainedStep / ConstrainedStep counts
//     1 step; AppendConstrainedToken appends exactly 1 token. EOS break skips
//     append, still steps+1. ✓
//
//   Phase 3: CloseSpanWithinBudget postcondition: |generatedOut| <= |generated_old|
//     + closeB; we add closeB to steps, so the invariant is preserved. ✓
//
//   Phase 4: UnconstrainedStep counts 1 step and appends at most 1 token. ✓
//
//   Phases 5, 6: same as Phases 2, 3. ✓
//
//   Phase 7: OpenConstrainedSpan appends "<<" (1 token), steps+1. Inner loop same
//     as Phase 2. Close same as Phase 3. ✓
//
//   Phase 8: same as Phase 3. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math word problem step by step. At the end write the COMPLETE combined arithmetic formula: <<EXPR>> where EXPR uses the problem variable names and operators (+, -, *, /, parentheses). The formula must compute the full final answer in one expression. Do NOT write a single variable or a partial sub-step. Examples of good formulas: <<n1*c1 + n2*c2 + c3>>, <<total - (total*frac + daily*period*7)>>, <<(n*m)//k>>, <<int(n1*frac1 + n2*mult1)>>. Include every variable and every operation needed.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;
var minSpanTokens: nat := 5;
var innerStepLimit: nat := 80;
var chunkSize: nat := 40;

var freeLimit: nat := (maxSteps * 7) / 10;
if freeLimit == 0 && maxSteps > 0 { freeLimit := 1; }
if freeLimit > maxSteps { freeLimit := maxSteps; }

var closeReserve: nat := 80;
if closeReserve > maxSteps { closeReserve := maxSteps; }
var constLimit: nat := maxSteps;
if maxSteps >= closeReserve { constLimit := maxSteps - closeReserve; }
if constLimit < freeLimit { constLimit := freeLimit; }
if constLimit > maxSteps { constLimit := maxSteps; }

// Phase 1: Unconstrained chunks watching for "<<"
while steps < freeLimit && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeLimit - steps
{
  var actualChunk: nat := chunkSize;
  if steps + actualChunk > freeLimit { actualChunk := freeLimit - steps; }
  if actualChunk == 0 { break; }
  var cg1, stoppedOnOpen, stoppedOnEos, stepsUsed1 := helpers.UnconstrainedChunk(lm, prompt, generated, actualChunk, "<<", eosToken);
  generated := cg1;
  steps := steps + stepsUsed1;
  if stoppedOnEos { break; }
  if stoppedOnOpen {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2: Constrained generation inside span
var innerSteps: nat := 0;
while insideConstrainedOut && steps < constLimit && innerSteps < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps
{
  if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg2, ci2, cc2 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    hasCompletedSpan := true;
  } else {
    var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2: Token;
    if |currentConstrainedOut| < minSpanTokens {
      next2 := helpers.SafePenalizedConstrainedStep(lm, parser, cp2, currentConstrainedOut, [eosToken], 8.0, eosToken);
    } else {
      next2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
    }
    steps := steps + 1;
    innerSteps := innerSteps + 1;
    if next2 == eosToken { break; }
    var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
    generated := ag2;
    insideConstrainedOut := ai2;
    currentConstrainedOut := ac2;
  }
}

// Phase 3: Force close if still open
if insideConstrainedOut && steps < maxSteps {
  var rem3 := maxSteps - steps;
  var closeB3: nat := 60;
  if closeB3 > rem3 { closeB3 := rem3; }
  if closeB3 > 0 {
    var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB3);
    generated := wg3;
    insideConstrainedOut := wi3;
    currentConstrainedOut := wc3;
    steps := steps + closeB3;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// Phase 4: Continue free generation if no span detected yet
while !insideConstrainedOut && !hasCompletedSpan && steps < freeLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeLimit - steps
{
  var next4 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next4 == eosToken { break; }
  generated := generated + [next4];
  if RenderedEndsWith(generated, "<<") {
    var eg4, ei4, ec4 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg4;
    insideConstrainedOut := ei4;
    currentConstrainedOut := ec4;
  }
}

// Phase 5: Constrained generation for span entered in Phase 4
var innerSteps5: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < constLimit && innerSteps5 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps5
{
  if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
    var cg5, ci5, cc5 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    steps := steps + 1;
    generated := cg5;
    insideConstrainedOut := ci5;
    currentConstrainedOut := cc5;
    hasCompletedSpan := true;
  } else {
    var cp5 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next5: Token;
    if |currentConstrainedOut| < minSpanTokens {
      next5 := helpers.SafePenalizedConstrainedStep(lm, parser, cp5, currentConstrainedOut, [eosToken], 8.0, eosToken);
    } else {
      next5 := helpers.ConstrainedStep(lm, parser, cp5, currentConstrainedOut, eosToken);
    }
    steps := steps + 1;
    innerSteps5 := innerSteps5 + 1;
    if next5 == eosToken { break; }
    var ag5, ai5, ac5 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next5);
    generated := ag5;
    insideConstrainedOut := ai5;
    currentConstrainedOut := ac5;
  }
}

// Phase 6: Force close if still open
if insideConstrainedOut && steps < maxSteps {
  var rem6 := maxSteps - steps;
  var closeB6: nat := 60;
  if closeB6 > rem6 { closeB6 := rem6; }
  if closeB6 > 0 {
    var wg6, wi6, wc6 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB6);
    generated := wg6;
    insideConstrainedOut := wi6;
    currentConstrainedOut := wc6;
    steps := steps + closeB6;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// Phase 7: Force open a span if none completed
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg7, fi7, fc7 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg7;
  insideConstrainedOut := fi7;
  currentConstrainedOut := fc7;
  steps := steps + 1;

  var innerSteps7: nat := 0;
  var innerLimit7: nat := 40;
  while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps7 < innerLimit7
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + innerLimit7 - innerSteps7
  {
    if |currentConstrainedOut| >= minSpanTokens && parser.IsCompletePrefix(currentConstrainedOut) {
      var cg7, ci7, cc7 := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      generated := cg7;
      insideConstrainedOut := ci7;
      currentConstrainedOut := cc7;
      hasCompletedSpan := true;
    } else {
      var cp7 := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next7: Token;
      if |currentConstrainedOut| < minSpanTokens {
        next7 := helpers.SafePenalizedConstrainedStep(lm, parser, cp7, currentConstrainedOut, [eosToken], 8.0, eosToken);
      } else {
        next7 := helpers.ConstrainedStep(lm, parser, cp7, currentConstrainedOut, eosToken);
      }
      steps := steps + 1;
      innerSteps7 := innerSteps7 + 1;
      if next7 == eosToken { break; }
      var ag7, ai7, ac7 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next7);
      generated := ag7;
      insideConstrainedOut := ai7;
      currentConstrainedOut := ac7;
    }
  }

  if insideConstrainedOut && steps < maxSteps {
    var rem7 := maxSteps - steps;
    var closeB7: nat := 40;
    if closeB7 > rem7 { closeB7 := rem7; }
    if closeB7 > 0 {
      var wg7, wi7, wc7 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB7);
      generated := wg7;
      insideConstrainedOut := wi7;
      currentConstrainedOut := wc7;
      steps := steps + closeB7;
    }
  }
}

// Phase 8: Final safety close with all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var finalBudget := maxSteps - steps;
  if finalBudget > 0 {
    var wg8, wi8, wc8 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, finalBudget);
    generated := wg8;
    insideConstrainedOut := wi8;
    currentConstrainedOut := wc8;
    steps := steps + finalBudget;
  }
}

cost := steps;
